<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, type Dashboard, type Department } from '../api/client'
import { useSession } from '../stores/session'
import { adminLinks } from '../router'
import BrandMark from '../components/BrandMark.vue'
import FeedbackBox from '../components/FeedbackBox.vue'
import StaffManager from '../features/administration/StaffManager.vue'
import RoleMatrix from '../features/administration/RoleMatrix.vue'
import AuditTable from '../features/administration/AuditTable.vue'
import SupportLookup from '../features/administration/SupportLookup.vue'
const session = useSession(), route = useRoute(), router = useRouter(), open = ref(false)
const active = computed(() => adminLinks.find(link => link.path === route.path))
const links = computed(() => adminLinks.filter(link => session.can(link.permission)))
const overview = ref<Dashboard | null>(null), department = ref<Department | null>(null), error = ref(''), loading = ref(false)
const areas: Record<string,string[]> = { finance: ['Revenue & payments','Expenses & carrier costs','Refunds & invoices'], marketing: ['Campaigns','Conversion insights'], operations: ['Shipment operations','Fulfillment monitoring'], support: ['Support cases'], carriers: ['Provider integrations','Carrier configuration'], qa: ['Test execution','Issue management'] }
let generation = 0
watch(() => route.path, async path => { const current = ++generation; error.value = ''; overview.value = null; department.value = null; open.value = false; loading.value = true
  try { if (path === '/admin') { const data = await api<Dashboard>('/admin/dashboard'); if (generation === current) overview.value = data } else if (areas[path.split('/')[2]]) { const data = await api<Department>('/admin/departments/'+path.split('/')[2]); if (generation === current) department.value = data } }
  catch (e) { if (generation === current) error.value = String(e) } finally { if (generation === current) loading.value = false }
}, { immediate: true })
async function logout() { try { await session.logout(); await router.push('/login') } catch (e) { error.value = String(e) } }
</script>
<template><div class="admin-shell"><aside class="sidebar" :class="{ open }"><BrandMark /><div class="workspace-label"><span class="workspace-avatar">S</span><div><strong>ShipWise workspace</strong><small>Administration · Phase 1</small></div></div><span class="nav-label">WORKSPACE</span><nav aria-label="Administration"><RouterLink v-for="link in links" :key="link.path" :to="link.path" :class="{ active: route.path === link.path }"><span aria-hidden="true">{{ link.symbol }}</span>{{ link.label }}</RouterLink></nav><div class="sidebar-foot"><span class="status-dot"></span> Foundation release <small>v0.1.0 · Development</small></div></aside><div class="admin-body"><header class="admin-topbar"><button class="mobile-menu secondary" :aria-expanded="open" aria-label="Toggle navigation" @click="open = !open">☰</button><span>Workspace <span class="crumb-divider">/</span> <strong>{{ active?.label }}</strong></span><div class="user-menu"><span class="user-avatar">{{ session.user?.name.slice(0,1) }}</span><div><strong>{{ session.user?.name }}</strong><small>{{ session.user?.roles.join(', ').replaceAll('_',' ') }}</small></div><button class="text-button" @click="logout">Sign out ↗</button></div></header><main class="admin-main"><div class="page-heading"><div><span class="eyebrow">YOUR SHIPWISE WORKSPACE</span><h1>{{ active?.label }}<span class="heading-dot">.</span></h1></div><span class="release-tag">PHASE 01 <span>Foundation</span></span></div><FeedbackBox :error="error" :loading="loading" /><template v-if="overview"><p class="lead">A clear picture of your platform, built on real account activity.</p><div class="metric-grid"><article class="metric"><span>Registered customers <span>↗</span></span><strong>{{ overview.customerCount }}</strong><small>All registered customer accounts</small></article><article class="metric"><span>Active team members <span>♧</span></span><strong>{{ overview.activeStaffCount }}</strong><small>Staff accounts with active access</small></article><article class="metric health-metric"><span>Platform status <span>◉</span></span><strong>Available</strong><small>API responding · {{ overview.health.version }}</small></article></div><div class="overview-grid"><section class="panel"><div class="section-toolbar"><h2>Recent security activity</h2><RouterLink v-if="session.can('audit.read')" class="text-link" to="/admin/audit">View audit trail ↗</RouterLink></div><ul v-if="overview.recentAudit?.length" class="activity-list"><li v-for="event in overview.recentAudit.slice(0,6)" :key="event.id"><span class="activity-symbol">↗</span><div><strong>{{ event.action.replaceAll('.',' · ').replaceAll('_',' ') }}</strong><small>{{ new Date(event.created_at).toLocaleString() }}</small></div><span class="badge">Recorded</span></li></ul><div v-else class="empty"><h3>A fresh start.</h3><p>Security events will appear here as your team uses ShipWise.</p></div></section><section class="panel"><span class="eyebrow">ACCOUNT OVERVIEW</span><h2>Access at a glance</h2><div v-for="status in overview.accountStatuses" :key="status.status" class="status-row"><span class="badge" :class="status.status">{{ status.status.replaceAll('_',' ') }}</span><strong>{{ status.count }}</strong></div><RouterLink v-if="session.can('staff.read')" class="button wide" to="/admin/staff">Manage your team ↗</RouterLink></section></div><section class="roadmap-card"><span class="roadmap-icon">↗</span><div><span class="eyebrow">THE FOUNDATION IS JUST THE BEGINNING</span><h2>Ready for the next chapter.</h2><p>Carrier comparison, shipment booking and payments will arrive in future phases. No shipping or financial activity is available yet.</p></div><span class="badge">Looking ahead</span></section></template><StaffManager v-if="route.path === '/admin/staff'" /><RoleMatrix v-if="route.path === '/admin/access-control'" /><AuditTable v-if="route.path === '/admin/audit'" /><template v-if="department"><p class="lead">Your {{ department.department }} workspace, ready for what comes next.</p><section v-if="department.department === 'qa'" class="panel"><h2>Release information</h2><div class="feature-grid"><div><span class="eyebrow">VERSION</span><h3>{{ department.version }}</h3></div><div><span class="eyebrow">ENVIRONMENT</span><h3>{{ department.environment }}</h3></div><div><span class="eyebrow">API</span><h3>{{ department.health }}</h3></div></div><p class="fine">Deployment details are limited to safe build metadata. Test execution integrations are not connected.</p></section><section v-if="department.department === 'marketing'" class="panel"><span class="eyebrow">ACCOUNT GROWTH</span><h2>{{ department.customerCount }} registered customers</h2><p class="muted">Aggregate count only. Personal customer data is restricted.</p></section><SupportLookup v-if="department.department === 'support' && session.can('customers.read_limited')" /><div class="feature-grid department-grid"><article v-for="area in areas[department.department]" :key="area" class="panel empty-area"><span class="empty-icon">↗</span><span class="eyebrow">FUTURE PHASE</span><h2>{{ area }}</h2><p>Not available in Phase 1. {{ department.message }}</p><span class="badge neutral">No activity yet</span></article></div></template><footer class="workspace-footer"><span>ShipWise AI · A foundation for better shipping.</span><span>Secure access. Clear responsibilities.</span></footer></main></div></div></template>